  <script>
    // 1. Plural rules calculation for Arabic with pinned Western digits (UAE convention)
    (function initPlural() {
      const count = 3;
      const pluralForms = {
        zero: 'لا توجد عناصر في هذا الطلب',
        one: 'لديك عنصر واحد في هذا الطلب',
        two: 'لديك عنصران في هذا الطلب',
