        many: 'لديك {count} عنصرًا في هذا الطلب',
        other: 'لديك {count} عنصر في هذا الطلب',
      };

      const pr = new Intl.PluralRules('ar');
      const rule = pr.select(count);
      const digitsFormatter = new Intl.NumberFormat('ar-AE-u-nu-latn');
      const line = pluralForms[rule].replace('{count}', digitsFormatter.format(count));

      const container = document.getElementById('order-items-line');
      if (container) {
        container.textContent = line;
      }
    })();

    // 2. Computed Umm al-Qura Hijri date with explicit 'Asia/Dubai' timeZone
    (function initDates() {
