        const hijriFormatter = new Intl.DateTimeFormat('ar-AE-u-ca-islamic-umalqura-nu-latn', {
          timeZone: 'Asia/Dubai',
          day: 'numeric',
          month: 'long',
          year: 'numeric'
        });

